#include <iostream>

// Khai báo nguyên mẫu hàm với đối số mặc định
void printArea(double radius = 1.0);

// Định nghĩa hàm
void printArea(double radius) {
    double area = radius * radius * 3.14159;
    std::cout << "area is " << area << "\n";
}

int main() {
    // Gọi hàm không truyền đối số -> sử dụng radius mặc định = 1.0
    printArea();
    // Gọi hàm có truyền đối số rõ ràng
    printArea(4);
    return 0;
}

