#include <iostream>

// Định nghĩa hàm inline
inline void displayDate(int month, int year) {
    std::cout << "month is " << month << "\n";
    std::cout << "year is " << year << "\n";
}

int main() {
    int month = 10, year = 2008;
    // Khi biên dịch, hai lời gọi này có thể được mở rộng trực tiếp tại chỗ
    displayDate(month, year);
    displayDate(9, 2010);
    return 0;
}

#include <iostream>

void t1();
void t2();

// Biến toàn cục, tự động nhận giá trị mặc định là 0
int y;

void t1() {
    int x = 1;
    std::cout << "x is " << x << "\n";
    std::cout << "y is " << y << "\n";
    x++;
    y++;
}

void t2() {
    // Biến cục bộ x ở t2 độc lập hoàn toàn với x ở t1
    int x = 1;
    std::cout << "x is " << x << "\n";
    std::cout << "y is " << y << "\n";
}

int main() {
    t1();
    t2();
    return 0;
}
